import sys
binf, symf, outf = sys.argv[1], sys.argv[2], sys.argv[3]
data = open(binf, "rb").read()
want = {"Entry_Init":"VT_ENTRY_INIT", "Entry_UnInit":"VT_ENTRY_UNINIT",
        "Entry_Play":"VT_ENTRY_PLAY", "pl_PlayFlag":"VT_PL_PLAYFLAG",
        "pl_ThisSong":"VT_PL_THISSONG", "TuneStart":"VT_TUNE_ADDR"}
sym = {}
for line in open(symf):
    p = line.split()
    if len(p) >= 2 and p[0] in want:
        sym[want[p[0]]] = int(p[1], 16)
with open(outf, "w") as o:
    o.write("/* GENERATED by victracker/build_player.sh -- do not edit.\n")
    o.write(" * Daniel Kahlin's VIC-TRACKER 2.0 player (BSD), assembled from\n")
    o.write(" * victracker/harness.asm. Position-fixed blob loaded at $%04X.\n */\n" % 0x2000)
    o.write("#pragma once\n#include <cstdint>\n\n")
    o.write("static constexpr uint16_t VT_BLOB_ORG = 0x2000;\n")
    for k in ["VT_ENTRY_INIT","VT_ENTRY_UNINIT","VT_ENTRY_PLAY",
              "VT_PL_PLAYFLAG","VT_PL_THISSONG","VT_TUNE_ADDR"]:
        o.write("static constexpr uint16_t %s = 0x%04X;\n" % (k, sym[k]))
    o.write("\nstatic const uint8_t vtplayer_bin[] = {\n")
    for i in range(0, len(data), 16):
        o.write("    " + ",".join("0x%02x" % b for b in data[i:i+16]) + ",\n")
    o.write("};\n")
    o.write("static constexpr unsigned vtplayer_bin_len = %d;\n" % len(data))
print("symbols:", sym)
